 // Return workspace, with physical custody and money shown as separate decisions.
 const closureApi=globalThis.RodavoltClosure;
 function closureStatement(id){const s=closureApi.statement(ops,id);return `<p class="notice">Este demonstrativo não compensa valores. Aluguel, crédito da loja e caução mantêm seus registros e exigem conferência própria.</p>${row('Aluguéis em aberto',cash(s.rentDue))}${row('Outros valores a receber',cash(s.otherReceivable))}${row('Crédito da lojinha do motorista',cash(s.driverCredit))}${row('Caução a devolver / conferir',cash(s.depositBalance),'Saldo em '+date(s.depositAsOf)+'. Não é receita nem desconto automático.')}${row('Ajuste de aluguel a devolver',cash(s.rentalRefund))}${row('Outros compromissos a pagar',cash(s.otherPayable))}<details class="gap"><summary>Ver a origem dos aluguéis</summary>${table(['Cobrança','Vencimento','Situação','Saldo'],s.charges.map(c=>`<tr><td>${esc(c.id)}</td><td>${date(c.date)}</td><td>${esc(c.status==='paid'?'Pago':c.status==='cancelled'?'Cancelado':'Em aberto')}</td><td>${cash(c.balance)}</td></tr>`).join(''))}</details>${s.rental?.requiresConfiguration?`<p class="notice amber gap">${esc(s.rental.reason)} Confira manualmente a abertura; não será inventada uma cobrança ou ajuste.</p>`:''}`;}
 function closurePanel(driverId=null){const records=closureApi.list(ops,driverId),active=ops.drivers.filter(d=>d.stage==='active'&&(!driverId||d.id===driverId));return `<div class="notice">Devolução guiada: agendar → vistoriar → receber carro e chaves → conferir kit → conferir saldos → encerrar. Dívida não desaparece e avaria não vira débito automático.</div>${active.length?`<div class="actions gap">${active.map(d=>btn('Agendar / acompanhar · '+esc(d.name),'closure-start','',`data-driver-id="${d.id}"`)).join('')}</div>`:''}<div class="gap">${records.length?records.map(r=>panel(esc(r.driverName)+' · '+r.vehicleId,row('Devolução combinada',date(r.plannedDate)+' · '+esc(r.plannedTime||'10:00'))+row('Situação',tag(r.status==='closed'?'Vínculo encerrado':r.physical?'Carro recebido · conferências pendentes':'Devolução em andamento',r.status==='closed'?'green':'amber'))+btn('Abrir devolução','closure-open','',`data-id="${r.id}"`))).join(''):'<p class="caption">Nenhuma devolução agendada. O carro permanece com o motorista até a conferência física.</p>'}</div>`;}
 function closureDetail(id){const r=closureApi.lookup(ops,id),s=closureApi.status(ops,id),inventory=H.inventory(ops,r.driverId),inspection=s.inspection,closed=r.status==='closed';return row('Motorista / carro',esc(r.driverName)+' · '+esc(r.vehicleId),'Ciclo '+(r.deliveryCycle+1)+' · '+r.id)+row('Combinado',date(r.plannedDate)+' · '+esc(r.plannedTime||'10:00'),esc(r.note))+`<div class="gap">${panel('1. Vistoria de devolução',inspection?row('Conferência aprovada',esc(inspection.id),num(inspection.km)+' km · combustível '+num(inspection.fuel)+'%'):`<p>O motorista preenche a vistoria no app. A gestão confere os itens e as fotos de exemplo.</p><div class="actions">${btn('Abrir vistoria no app','closure-inspect','primary',`data-id="${r.id}"`)}${btn('Conferir vistorias enviadas','inspection-admin')}</div>`)}</div><div class="gap">${panel('2. Carro e chaves recebidos',r.physical?row('Recebimento físico confirmado',date(r.physical.date),num(r.physical.km)+' km · '+esc(r.physical.note)):inspection?`<form id="closure-physical-form"><input type="hidden" name="entityId" value="${r.id}">${input('date','Data do recebimento',K.operatingDate,'type="date" required')}<input type="hidden" name="driverId" value="${r.driverId}"><input type="hidden" name="vehicleId" value="${r.vehicleId}"><input type="hidden" name="km" value="${inspection.km}"><input type="hidden" name="fuel" value="${inspection.fuel}"><label class="check gap"><input name="keysReceived" type="checkbox" required>Recebi este carro e todas as chaves. Conferi ${num(inspection.km)} km e ${num(inspection.fuel)}% de combustível.</label><label class="field gap">Parecer do recebimento<textarea name="note" rows="2" required maxlength="1000"></textarea></label><div class="form-actions"><button class="btn primary" type="submit">Confirmar recebimento físico</button></div></form>`:'<p class="caption">Aguardando a vistoria de devolução aprovada.</p>')}</div><div class="gap">${panel('3. Retorno do kit',closed||r.kitReceiptIds.length&&!inventory.products.some(p=>p.qty>0)?row('Kit conferido',r.kitReceiptIds.map(esc).join(', '),'Produtos avariados ficam em quarentena, sem cobrança automática.'):`<form id="closure-kit-form"><input type="hidden" name="entityId" value="${r.id}"><p class="caption">Confira todo o kit. Informe quantas unidades estão avariadas; as demais voltam ao estoque central. Avaria será avaliada separadamente.</p>${table(['Produto','Sob custódia','Avariados'],inventory.products.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.qty}</td><td>${input('damaged-'+p.id,'Quantidade avariada',0,`type="number" min="0" max="${p.qty}" step="1" required`)}</td></tr>`).join(''))}<label class="field gap">Registro da conferência<textarea name="note" rows="2" required maxlength="1000" placeholder="Conte o que foi devolvido e as condições dos produtos."></textarea></label><div class="form-actions"><button class="btn" type="submit">Confirmar retorno do kit</button></div></form>`)}</div><div class="gap">${panel('4. Demonstrativo e encerramento',closureStatement(id)+(closed?`<p class="notice green gap">Vínculo encerrado em ${date(r.closedDate)}. O carro só foi liberado após a conferência física. Manutenção aberta mantém o carro indisponível.</p><p>${esc(r.finalNote)}</p>`:`${s.blockers.length?`<div class="notice amber gap"><strong>Ainda falta:</strong><ul>${s.blockers.map(b=>`<li>${esc(b)}</li>`).join('')}</ul></div>`:''}<form id="closure-close-form" class="gap"><input type="hidden" name="entityId" value="${r.id}"><label class="check"><input type="checkbox" name="statementChecked" required>Conferi o demonstrativo. Os saldos permanecem separados, sem compensação automática.</label>${s.rental?.requiresConfiguration?'<label class="check"><input type="checkbox" name="openingBalanceChecked" required>Conferi manualmente os aluguéis da abertura, sem agenda contratual calculada.</label>':''}<label class="field gap">Parecer final<textarea name="note" required rows="2" maxlength="1000"></textarea></label><div class="form-actions"><button type="submit" class="btn primary" ${s.ok?'':'disabled'}>Encerrar vínculo e liberar carro</button></div></form>`))}</div>${closed?`<div class="gap">${panel('5. Devolução da caução',`<p class="caption">Registre somente depois da conferência. O lançamento é fictício e não envia dinheiro ao banco.</p>${closureApi.statement(ops,id).depositBalance>0?btn('Registrar devolução de caução','closure-refund','',`data-id="${r.id}"`):'<p>Sem saldo de caução nesta data.</p>'}${r.refunds.length?table(['Referência','Data','Valor'],r.refunds.map(f=>`<tr><td>${esc(f.reference)}</td><td>${date(f.date)}</td><td>${cash(f.amount)}</td></tr>`).join('')):''}`)}</div>`:''}`;}
 function driverClosureStatus(driverId){const r=closureApi.list(ops,driverId)[0];if(!r)return '';return `<section class="driver-paper gap"><h2>${r.status==='closed'?'Sua devolução foi conferida':'Devolução do carro'}</h2><p>${r.status==='closed'?'A RODAVOLT recebeu o carro. Você pode acompanhar seus saldos no aluguel e pedir ajuda.':'Combinado: '+date(r.plannedDate)+' às '+esc(r.plannedTime||'10:00')+'. Leve o carro, as chaves e os produtos restantes.'}</p>${r.status!=='closed'?`<button type="button" class="btn" data-action="closure-driver-inspect" data-id="${r.id}">Fazer vistoria de devolução</button>`:''}</section>`;}
 function closureAction(action,e){if(!action.startsWith('closure-'))return false;const id=e.dataset.id,driverId=e.dataset.driverId;if(mode==='driver'&&action!=='closure-driver-inspect')throw new RangeError('A conferência da devolução é feita pela gestão.');if(action==='closure-panel'){open('Devolução e encerramento',closurePanel(driverId));return true;}if(action==='closure-start'){const d=M.driver(ops,driverId),existing=closureApi.list(ops,d.id).find(r=>r.vehicleId===d.vehicleId&&r.deliveryCycle===(d.deliveryCycle||0));if(existing){open('Devolução · '+existing.id,closureDetail(existing.id));return true;}open('Agendar devolução',`<form id="closure-start-form"><input type="hidden" name="driverId" value="${d.id}">${row('Motorista / carro',esc(d.name)+' · '+esc(d.vehicleId))}<div class="fields gap">${input('date','Data combinada',K.operatingDate,'type="date" required')}${input('time','Hora combinada','10:00','type="time" required')}</div><label class="field gap">O que foi combinado<textarea name="note" required rows="3" maxlength="1000"></textarea></label><div class="form-actions"><button type="submit" class="btn primary">Agendar devolução</button></div></form>`);return true;}if(action==='closure-open'){open('Devolução · '+id,closureDetail(id));return true;}if(action==='closure-inspect'||action==='closure-driver-inspect'){const record=closureApi.lookup(ops,id);if(mode==='driver'&&record.driverId!==activeDriverId)throw new RangeError('Esta devolução não pertence ao seu perfil.');const current=I.ensure(ops).records.filter(v=>v.driverId===record.driverId&&v.vehicleId===record.vehicleId&&(v.deliveryCycle||0)===record.deliveryCycle&&v.type==='return').at(-1),r=current||I.create(ops,{driverId:record.driverId,vehicleId:record.vehicleId,type:'return'});activeDriverId=record.driverId;mode='driver';driverPage='inspection';inspectionSelectedId=r.id;inspectionStartNew=false;close();render();persist();return true;}if(action==='closure-refund'){const r=closureApi.lookup(ops,id),s=closureApi.statement(ops,id),accounts=ops.finance?.accounts||[];open('Registrar devolução de caução',`<form id="closure-refund-form"><input type="hidden" name="entityId" value="${r.id}"><p class="notice">Registro fictício. Confira a devolução pelo extrato; este botão não faz transferência.</p><div class="fields gap">${input('amount','Valor da caução a devolver · R$',s.depositBalance,`type="number" min="0.01" max="${s.depositBalance}" step="0.01" required`)}${input('date','Data',r.closedDate,'type="date" required')}${select('accountId','Conta demonstrativa',accounts[0]?.id||'BANK-1',accounts.length?accounts.map(a=>[a.id,a.name]):[['BANK-1','Conta do livro de exemplo']])}${input('reference','Referência única e motivo','','required maxlength="100"')}</div><label class="check gap"><input type="checkbox" name="confirm" required>Conferi o registro demonstrativo e os saldos.</label><div class="form-actions"><button type="submit" class="btn primary">Registrar devolução de exemplo</button></div></form>`);return true;}return false;}
 function closureSubmit(form,f){if(!form.id.startsWith('closure-'))return false;if(mode!=='admin')throw new RangeError('A conferência da devolução é feita pela gestão.');let id=String(f.get('entityId')||''),message='Conferência registrada.';if(form.id==='closure-start-form'){id=closureApi.start(ops,{driverId:String(f.get('driverId')),date:String(f.get('date')),time:String(f.get('time')),note:String(f.get('note'))}).id;message='Devolução agendada. O carro continua vinculado.';}else if(form.id==='closure-physical-form'){closureApi.recordPhysicalReceipt(ops,id,{driverId:String(f.get('driverId')),vehicleId:String(f.get('vehicleId')),date:String(f.get('date')),km:Number(f.get('km')),fuel:Number(f.get('fuel')),keysReceived:f.has('keysReceived'),note:String(f.get('note'))});message='Recebimento físico registrado.';}else if(form.id==='closure-kit-form'){const r=closureApi.lookup(ops,id),inventory=H.inventory(ops,r.driverId);closureApi.recordKit(ops,id,{lines:inventory.products.map(p=>({productId:p.id,good:p.qty-Number(f.get('damaged-'+p.id)),damaged:Number(f.get('damaged-'+p.id))})),note:String(f.get('note'))});message='Retorno do kit conferido, sem débito automático.';}else if(form.id==='closure-close-form'){closureApi.close(ops,id,{statementChecked:f.has('statementChecked'),openingBalanceChecked:f.has('openingBalanceChecked'),note:String(f.get('note'))});message='Vínculo encerrado. Os saldos foram preservados.';}else if(form.id==='closure-refund-form'){if(!f.has('confirm'))throw new RangeError('Confirme a conferência do registro.');closureApi.refundDeposit(ops,id,{amount:Number(f.get('amount')),date:String(f.get('date')),accountId:String(f.get('accountId')),reference:String(f.get('reference'))});message='Devolução de caução registrada uma vez no livro demonstrativo.';}else return false;persist();render();open('Devolução · '+id,closureDetail(id));toast(message);return true;}
